const quizQuestions = [
  {prompt:'Two Pods can communicate on the same node, but not across nodes. What should you check next?',options:['Change the application HTTP route','Check CNI routes or encapsulation and node firewall rules','Replace the Pod with a LoadBalancer Service','Increase the DNS TTL'],answer:1,explanation:'Same-node traffic works, so focus on the network path between nodes.'},
  {prompt:'A Pod gets NXDOMAIN for api.team.svc.cluster.local, while a laptop resolves a public API name. What is the best first check?',options:['Check the Service name, namespace, and DNS query from inside the Pod','Inspect the API TLS certificate','Change the node public IP','Change the browser route'],answer:0,explanation:'NXDOMAIN means the queried name was not found. Verify the exact Kubernetes Service name and namespace from the failing Pod.'},
  {prompt:'TCP connects to port 443, but TLS reports that the certificate name does not match the requested host. What should you inspect?',options:['The Pod CPU limit','The certificate names and TLS server name','The DNS TTL only','The client ephemeral port'],answer:1,explanation:'The TCP connection succeeded. The error points to certificate identity or hostname configuration.'},
  {prompt:'A gateway returns 503, and the Kubernetes Service has no ready endpoints. What should you check first?',options:['Pod readiness and the Service EndpointSlices','Whether the client uses HTTP or HTTPS','The DNS record expiration date','The browser cache'],answer:0,explanation:'With no ready endpoints, the Service has no healthy Pod to receive the request.'},
  {prompt:'A trace shows DNS took 8 ms, the gateway 12 ms, and the API 320 ms. Where should you investigate first?',options:['The DNS resolver','The gateway route','The API operation and its dependencies','The client network adapter'],answer:2,explanation:'The API span accounts for most of the measured delay. Follow its trace and logs.'},
  {prompt:'A NetworkPolicy allows frontend Pods to reach API Pods on TCP 8080, but the connection still fails. What should you verify?',options:['That the CNI enforces NetworkPolicy and the Pod labels match','That the browser has a valid DNS cache','That the API Service has a public IP','That both Pods run on the same node'],answer:0,explanation:'The policy must select the intended Pods, and the network plugin must enforce it.'},
  {prompt:'A request gets “connection refused” immediately. What does that usually indicate?',options:['DNS could not find the hostname','The destination responded, but no service accepted that port','A firewall silently dropped the packet','The TLS certificate expired'],answer:1,explanation:'A refusal usually means the host responded but no process accepted the connection on that port.'},
  {prompt:'A Pod resolves an API hostname to an IP, but curl times out while connecting. What should you investigate next?',options:['The DNS record spelling','The route, destination listener, and firewall or security-group rules','The certificate expiration date','The HTTP response body'],answer:1,explanation:'DNS worked. Check whether traffic can reach the destination port and whether a service is listening.'},
  {prompt:'Which signal gives a request-by-request timeline across several services?',options:['A DNS A record','A distributed trace with spans','A firewall allow rule','A container port mapping'],answer:1,explanation:'A distributed trace links timed spans from each service for one request, helping locate the slow or failing hop.'},
  {prompt:'Some requests behind a load balancer succeed and others fail. What is a useful first check?',options:['Compare backend health and readiness across all targets','Give every backend a new IP address','Increase the DNS TTL','Disable TLS'],answer:0,explanation:'An unhealthy or misconfigured backend can cause intermittent failures when the load balancer selects it.'},
  {prompt:'Which subnet contains 192.168.10.70/26?',options:['192.168.10.0/26','192.168.10.64/26','192.168.10.70/26','192.168.10.128/26'],answer:1,explanation:'A /26 divides the last octet into blocks of 64. .70 falls in the .64–.127 block.'},
  {prompt:'Which protocol-to-layer mapping is correct?',options:['TCP—Application; IP—Transport; HTTP—Link','TCP—Transport; IP—Internet; HTTP—Application; Ethernet—Link','TCP—Link; IP—Application; HTTP—Transport','TCP—Internet; IP—Link; HTTP—Transport'],answer:1,explanation:'This TCP/IP mapping is a practical troubleshooting model; OSI provides a more detailed seven-layer reference.'},
  {prompt:'A VPN tunnel reports “connected,” but users cannot reach a private service. What should you check next?',options:['Routes and permitted network ranges on both ends','The browser cache','The public site CDN','The HTTP response body'],answer:0,explanation:'A tunnel can be established while routes or allowed CIDRs still prevent traffic from reaching the private network.'},
  {prompt:'A client connects to one endpoint, which forwards /api requests to an internal application server. What role is that endpoint playing?',options:['Recursive DNS resolver','Reverse proxy','VPN client','CDN cache only'],answer:1,explanation:'A reverse proxy receives requests on behalf of servers and forwards them to the appropriate backend.'},
  {prompt:'A customer requests a cacheable image, and a nearby CDN edge already has a valid copy. What happens?',options:['The CDN serves its cached copy without contacting the origin for that request','The CDN restarts the origin','DNS rewrites the image contents','The browser opens a VPN tunnel'],answer:0,explanation:'A cache hit reduces latency and origin load. A cache miss may need to fetch from the origin.'},
  {prompt:'What does docker run -p 8080:80 nginx mean?',options:['Container port 8080 maps to host port 80','Host port 8080 maps to container port 80','Both host and container use port 8080','The container IP changes to port 80'],answer:1,explanation:'Port publishing uses host-port:container-port. Nginx listens on port 80 inside the container.'},
  {prompt:'DNS resolves and TCP/TLS connect, but GET /health returns HTTP 404. What does that most likely mean?',options:['The requested path was not found by the HTTP service','DNS failed to resolve the host','The TCP connection timed out','TLS certificate verification failed'],answer:0,explanation:'The request reached an HTTP service, but that path was not found. Check the route and endpoint configuration.'}
];

const slides = [
  {title:'Networking in DevOps', section:'01 · ORIENTATION', body:`<div class="slide hero"><div class="slide-kicker"><i class="kicker-dot"></i> A FIELD GUIDE FOR BUILDING AND OPERATING SERVICES</div><h1>Networking<br>in DevOps<span style="color:#438568">.</span></h1><p class="lead">Follow a request from a developer’s laptop to a running service. Learn the network concepts that make delivery reliable, observable, and secure.</p><div class="hero-bottom"><span class="pill">FOUNDATIONS → KUBERNETES</span><span class="pill">45 MIN · 7 SLIDES</span></div><div class="hero-meta"><div>BUILT FOR<b>Developers · SRE · Platform teams</b></div><div>YOU’LL LEAVE WITH<b>A practical troubleshooting path</b></div></div></div>`},
  {title:'The network is part of the product', section:'02 · WHY IT MATTERS', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> WHY IT MATTERS</div><div class="two-col"><div><h2>Every release<br>takes a route.</h2><p class="lead">Applications are distributed systems. A feature only works when every hop between client, service, and dependency works too.</p><p class="body-copy">In DevOps, teams define and change these paths alongside application code. Network behavior affects deploy speed, availability, security boundaries, and user experience.</p></div><div><div class="diagram"><div class="diagram-title">A REQUEST CROSSES MANY BOUNDARIES</div><div class="flow"><div class="node"><b>Browser</b><small>client</small></div><span class="arrow">→</span><div class="node"><b>Edge</b><small>DNS · TLS</small></div><span class="arrow">→</span><div class="node"><b>Service</b><small>app · data</small></div></div><div class="callout">A timeout can come from any hop. Measure and reason about the whole path.</div></div><div class="metric-row"><div class="metric"><strong>Reachability</strong><span>Can packets arrive?</span></div><div class="metric"><strong>Policy</strong><span>Should they?</span></div></div></div></div></div>`},
  {title:'A request, layer by layer', section:'03 · THE MODEL', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> THE MODEL</div><h2>Layers give you a map</h2><p class="lead">The TCP/IP model is a useful working map. Start at the layer where the symptom appears, then follow the dependencies below it.</p><div class="two-col" style="margin-top:16px"><div class="stack"><div class="layer l7"><b>Application</b><span>HTTP · DNS · gRPC</span></div><div class="layer l4"><b>Transport</b><span>TCP · UDP · ports</span></div><div class="layer l3"><b>Internet</b><span>IP · routing</span></div><div class="layer l2"><b>Link</b><span>Ethernet · Wi-Fi</span></div></div><div><div class="callout"><b>Example: HTTPS request</b><br>HTTP is carried in TLS, over TCP, inside IP packets, sent across a link. DNS typically resolves the host name before the connection starts.</div><p class="body-copy" style="margin-top:14px">OSI’s seven-layer model is a teaching aid; real protocols do not always fit neatly into one box. Use layer names to organize investigation, not as rigid boundaries.</p></div></div></div>`},
  {title:'Addressing and naming', section:'04 · IP, DNS & PORTS', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> IP, DNS & PORTS</div><h2>Find the right destination</h2><p class="lead">Names, addresses, and ports answer different questions. A healthy connection needs all three to line up.</p><div class="cards"><div class="card"><span class="card-index">01 / NAME</span><h3>DNS</h3><p>Maps a name such as <code>api.example.test</code> to one or more IP addresses. Check resolver choice, search domains, TTL, and stale records.</p></div><div class="card"><span class="card-index">02 / HOST</span><h3>IP address</h3><p>IPv4 and IPv6 identify interfaces and networks. Subnets define which destinations are local; routes direct traffic elsewhere.</p></div><div class="card"><span class="card-index">03 / PROCESS</span><h3>Port</h3><p>TCP or UDP port numbers select an application endpoint on a host. A listening port must be reachable through each policy boundary.</p></div></div><div class="callout">Fast check: resolve the exact hostname from the same runtime environment that reports the failure.</div></div>`},
  {title:'TCP, UDP and TLS', section:'05 · CONNECTIONS', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> CONNECTIONS</div><h2>Know what the handshake promises</h2><div class="split"><div class="compare"><div class="mini-label">TCP · RELIABLE STREAM</div><h3>Ordered bytes</h3><p>Handshake: client SYN → server SYN-ACK → client ACK. Sequence numbers order bytes; ACKs confirm received ranges. Retransmission repairs loss, receive windows limit sender rate for receiver capacity, and congestion control adapts to path load. TCP is a byte stream, not messages.</p><p><b>Use:</b> HTTPS, SSH, most database protocols.</p></div><div class="compare"><div class="mini-label">UDP · DATAGRAMS</div><h3>Lightweight messages</h3><p>UDP sends independent datagrams without built-in delivery or ordering guarantees. Applications handle reliability when they need it.</p><p><b>Use:</b> DNS queries, real-time media, QUIC transport.</p></div></div><div class="two-col" style="margin-top:18px"><div><h3>TLS adds identity and privacy</h3><p class="body-copy">TLS authenticates the server using certificates and encrypts application traffic. Failures often come from trust chains, hostname mismatch, or expiry.</p></div><div class="code"><span class="comment"># Check DNS, TCP reachability, and TLS together</span><br><span class="cmd">curl -v https://api.example.test/health</span></div></div></div>`},
  {title:'Containers need a network contract', section:'06 · CONTAINERS', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> CONTAINERS</div><h2>Containers add interfaces and namespaces</h2><p class="lead">A container gets an isolated network view. The runtime and network plugin connect that view to the host and other workloads.</p><div class="path"><div class="path-item"><span class="step">01 · CREATE</span><b>Network namespace</b><p>Interfaces, routes, and ports are scoped for the container.</p></div><span class="path-arrow">→</span><div class="path-item"><span class="step">02 · CONNECT</span><b>CNI plugin</b><p>Container Network Interface standardizes plugin setup and teardown.</p></div><span class="path-arrow">→</span><div class="path-item"><span class="step">03 · FORWARD</span><b>Host / overlay</b><p>Routes, bridges, encapsulation, and policy carry traffic.</p></div></div><div class="two-col" style="margin-top:21px"><div class="callout"><b>Worked port publish:</b> <code>-p 8080:80</code> maps host port 8080 to container port 80. On a typical bridge network, a veth pair connects the container namespace to a bridge; host forwarding/NAT and firewall rules decide whether remote clients can reach it. The process must listen on the container interface, not only 127.0.0.1.</div><div class="code"><span class="comment"># Publish host port 8080 to container port 80</span><br><span class="cmd">docker run -p 8080:80 nginx</span><br><span class="comment"># Verify what is listening on the host</span><br><span class="cmd">ss -lntp</span></div></div></div>`},
  {title:'Kubernetes networking in four paths', section:'07 · KUBERNETES', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> KUBERNETES</div><h2>Four paths, four questions</h2><p class="lead">Kubernetes networking becomes clearer when you separate the communication problems.</p><div class="cards"><div class="card"><span class="card-index">01 / SAME POD</span><h3>Container ↔ container</h3><p>Containers in one Pod share a network namespace and can communicate over localhost.</p></div><div class="card"><span class="card-index">02 / WORKLOAD</span><h3>Pod ↔ Pod</h3><p>The cluster network gives each Pod an address and enables cross-node connectivity through the installed network plugin.</p></div><div class="card"><span class="card-index">03 / DISCOVERY</span><h3>Pod ↔ Service</h3><p>A Service selects ready endpoints and gives clients a stable virtual IP and DNS name while Pod IPs change. The cluster dataplane (implementation varies) forwards traffic to EndpointSlice backends.</p></div></div><div class="two-col" style="margin-top:13px"><div class="compare"><div class="mini-label">NORTH–SOUTH</div><h3>Outside ↔ Service</h3><p>Use a supported LoadBalancer, Gateway API implementation, or Ingress controller to expose an application.</p></div><div class="compare"><div class="mini-label">CLUSTER CONTRACT</div><h3>Plugin responsibilities</h3><p>Kubernetes defines APIs. A CNI implementation provides Pod networking; policy enforcement depends on plugin support and configuration.</p></div></div></div>`},
  {title:'Expose services deliberately', section:'08 · SERVICES & GATEWAYS', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> SERVICES & GATEWAYS</div><h2>Stable names, controlled entry</h2><p class="lead">Separate internal discovery from external exposure. Give each route only the reach it needs.</p><div class="two-col"><div class="diagram"><div class="diagram-title">TYPICAL INBOUND REQUEST</div><div class="stack"><div class="layer l2"><b>Client</b><span>Internet / corporate</span></div><div class="layer l3"><b>Gateway / LoadBalancer</b><span>TLS · host · path</span></div><div class="layer l4"><b>Service</b><span>stable VIP / DNS</span></div><div class="layer l7"><b>Ready Pods</b><span>EndpointSlices</span></div></div></div><div><div class="mini-label">CHOOSE THE API BY INTENT</div><div class="resource-list"><div class="resource-row"><b>ClusterIP</b><span>Internal cluster access</span></div><div class="resource-row"><b>NodePort</b><span>Port on each node</span></div><div class="resource-row"><b>LoadBalancer</b><span>Cloud / provider entry point</span></div><div class="resource-row"><b>Gateway API</b><span>Expressive routing and roles</span></div></div><div class="callout">Ingress is widely used, but its API is frozen; Kubernetes recommends Gateway API for new capabilities.</div></div></div></div>`},
  {title:'Network policy is an allow list', section:'09 · SECURITY', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> SECURITY</div><h2>Make permitted paths explicit</h2><p class="lead">NetworkPolicy controls selected Pod traffic at IP and port level. A policy only works when the cluster’s network plugin implements enforcement.</p><div class="two-col" style="margin-top:10px"><div><div class="mini-label">A USEFUL POLICY DESIGN</div><div class="path" style="display:grid;grid-template-columns:1fr 1fr"><div class="path-item"><span class="step">INGRESS</span><b>Who can reach this app?</b><p>Allow the gateway and required peer workloads.</p></div><div class="path-item"><span class="step">EGRESS</span><b>What may it call?</b><p>Allow DNS and named dependencies; keep other routes closed where practical.</p></div><div class="path-item"><span class="step">IDENTITY</span><b>Which Pods match?</b><p>Use stable, meaningful labels and namespace selectors.</p></div><div class="path-item"><span class="step">VERIFY</span><b>Did enforcement apply?</b><p>Test allowed and denied flows from representative Pods.</p></div></div></div><div><div class="code"><span class="comment"># Inspect policies and selected Pods</span><br><span class="cmd">kubectl get networkpolicy -A</span><br><span class="cmd">kubectl describe networkpolicy -n app</span><br><span class="comment"># Check plugin and endpoints too</span><br><span class="cmd">kubectl get pods -o wide -n app</span></div><div class="callout">A Kubernetes NetworkPolicy object alone is not proof of isolation: confirm the CNI supports it and test the actual dataplane.</div></div></div></div>`},
  {title:'Observe the packet path', section:'10 · OBSERVABILITY', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> OBSERVABILITY</div><h2>Turn “it is down” into evidence</h2><p class="lead">Pair application signals with network signals. Ask where the request stops, and compare a working path with a failing one.</p><div class="path"><div class="path-item"><span class="step">01 · NAME</span><b>Resolve</b><p><code>dig</code> · DNS cache · search path</p></div><span class="path-arrow">→</span><div class="path-item"><span class="step">02 · ROUTE</span><b>Reach host</b><p><code>ip route</code> · <code>traceroute</code></p></div><span class="path-arrow">→</span><div class="path-item"><span class="step">03 · PORT</span><b>Open socket</b><p><code>ss</code> · <code>nc</code> · <code>curl</code></p></div><span class="path-arrow">→</span><div class="path-item"><span class="step">04 · APP</span><b>Check response</b><p>HTTP status · logs · traces</p></div></div><div class="split"><div class="compare"><div class="mini-label">METRICS</div><h3>How often and how slow?</h3><p>Connection errors, retransmits, DNS latency, request latency, and saturation over time.</p></div><div class="compare"><div class="mini-label">FLOWS & PACKETS</div><h3>Who talked to whom?</h3><p>Flow logs or packet captures reveal direction, policy verdicts, and protocol details. Protect sensitive payloads.</p></div></div></div>`},
  {title:'A repeatable troubleshooting loop', section:'11 · PRACTICE', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> PRACTICE</div><h2>Trace from the caller outward</h2><p class="lead">Work from one failing request. Change one variable at a time and keep the evidence.</p><div class="two-col" style="margin-top:12px"><div class="path" style="display:grid;grid-template-columns:1fr 1fr"><div class="path-item"><span class="step">1 · SCOPE</span><b>Who fails?</b><p>One client, one zone, all Pods, or all users?</p></div><div class="path-item"><span class="step">2 · NAME</span><b>Resolve correctly?</b><p>Check DNS answer inside the same environment.</p></div><div class="path-item"><span class="step">3 · ENDPOINT</span><b>Is the app ready?</b><p>Check Service selectors, EndpointSlices, readiness.</p></div><div class="path-item"><span class="step">4 · PATH</span><b>Can the socket connect?</b><p>Check routes, listeners, policies, firewalls, security groups.</p></div></div><div><div class="code"><span class="comment"># Start with service selection and endpoints</span><br><span class="cmd">kubectl get svc,endpointslice -n app</span><br><span class="comment"># Compare a request from inside the cluster</span><br><span class="cmd">kubectl exec deploy/debug -- curl -sv http://api.app</span><br><span class="comment"># Then inspect workload and node events</span><br><span class="cmd">kubectl describe pod -n app</span></div><div class="callout"><b>Common clue:</b> timeout suggests packets are dropped or unanswered; “connection refused” usually means the host responded but no process accepted that port.</div></div></div></div>`},
  {title:'Quick knowledge check', section:'12 · CHECK YOUR UNDERSTANDING', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> CHECK YOUR UNDERSTANDING</div><h2>Networking quiz</h2><p class="lead">17 questions covering the source guide and practical DevOps troubleshooting. Choose an answer to see why.</p><div class="quiz-head"><span id="quiz-progress-text"></span><span id="quiz-score"></span></div><div class="quiz-progress-track"><div id="quiz-progress-bar"></div></div><section class="quiz-card"><h3 id="quiz-question" aria-live="polite"></h3><div class="quiz-options" id="quiz-options"></div><div id="quiz-feedback" class="quiz-feedback" aria-live="polite"></div></section><div class="quiz-controls"><button id="quiz-prev" class="btn btn-ghost" type="button">← Previous</button><button id="quiz-next" class="btn btn-primary" type="button">Next question →</button></div><p class="quiz-note">You can move between questions and change an answer. Your score updates as you go.</p></div>`},
  {title:'Keep learning, keep experimenting', section:'13 · NEXT STEPS', body:`<div class="slide"><div class="slide-kicker"><i class="kicker-dot"></i> NEXT STEPS · OPEN RESOURCES</div><h2>Use the source, then try it</h2><p class="lead">Start with the official model and specifications. Use project repositories to understand real implementations and inspect their examples.</p><div class="source-grid"><a class="source-card" href="https://kubernetes.io/docs/concepts/services-networking/" target="_blank" rel="noreferrer"><span class="external">↗</span><span class="source-type">OFFICIAL DOCUMENTATION</span><b>Kubernetes networking</b><p>Services, DNS, Gateway API, NetworkPolicy, and the Kubernetes network model.</p></a><a class="source-card" href="https://github.com/containernetworking/cni" target="_blank" rel="noreferrer"><span class="external">↗</span><span class="source-type">GITHUB · CNCF PROJECT</span><b>Container Network Interface</b><p>The CNI specification, libraries, and plugin integration context.</p></a><a class="source-card" href="https://github.com/cilium/cilium" target="_blank" rel="noreferrer"><span class="external">↗</span><span class="source-type">GITHUB · IMPLEMENTATION</span><b>Cilium</b><p>eBPF-based Kubernetes networking, security, and observability implementation.</p></a><a class="source-card" href="https://github.com/SystemsApproach/book" target="_blank" rel="noreferrer"><span class="external">↗</span><span class="source-type">GITHUB · OPEN TEXTBOOK</span><b>Computer Networking: Principles, Protocols and Practice</b><p>Open textbook for deeper networking fundamentals and protocol concepts.</p></a><a class="source-card" href="https://github.com/iam-veeramalla/a-to-z-of-networking/tree/main" target="_blank" rel="noreferrer"><span class="external">↗</span><span class="source-type">GITHUB · LEARNING GUIDE</span><b>A to Z of Networking for DevOps</b><p>Reference path for IP addressing, TCP/IP and OSI, DNS, HTTP/HTTPS, load balancing, firewalls, VPNs, proxies/CDNs, Docker and Kubernetes networking.</p></a></div><div class="two-col" style="margin-top:15px"><div class="compare final-card"><div class="mini-label">WATCH · CHANNELS</div><div class="resource-list"><div class="resource-row"><b>Kubernetes</b><a href="https://www.youtube.com/@KubernetesCommunity" target="_blank" rel="noreferrer">OFFICIAL COMMUNITY ↗</a></div><div class="resource-row"><b>CNCF</b><a href="https://www.youtube.com/@CNCF" target="_blank" rel="noreferrer">CONFERENCE TALKS ↗</a></div><div class="resource-row"><b>TechWorld with Nana</b><a href="https://www.youtube.com/@TechWorldwithNana" target="_blank" rel="noreferrer">STRUCTURED DEVOPS ↗</a></div><div class="resource-row"><b>Practical Networking</b><a href="https://www.youtube.com/@PracticalNetworking" target="_blank" rel="noreferrer">NETWORK FOUNDATIONS ↗</a></div></div></div><div class="compare"><div class="mini-label">TEAM EXERCISE</div><h3>Trace one real service</h3><p>Draw the path from client to Pod. Mark the DNS answer, each routing/policy boundary, and the signals you would inspect during an outage.</p><div class="callout">Keep this page open as a team reference. The navigation and arrow keys work for live walkthroughs.</div></div></div><p style="font:9px 'DM Mono',monospace;color:#9aa8a1;margin:13px 0 0">SOURCE LINKS CHECKED · 06 NOV 2026</p></div>`}
];

